sql.where:
C.CLUB_STATUS = 'ACTIVE'
AND C.CLUB_NAME LIKE #{keywordPattern} ESCAPE '!'
AND ( C.CLUB_SUMMARY LIKE #{keywordPattern} ESCAPE '!' OR C.CLUB_DESCRIPTION LIKE #{keywordPattern} ESCAPE '!' )
AND LEADER.NICKNAME LIKE #{keywordPattern} ESCAPE '!'
AND ( C.CLUB_NAME LIKE #{keywordPattern} ESCAPE '!' OR C.CLUB_SUMMARY LIKE #{keywordPattern} ESCAPE '!' OR C.CLUB_DESCRIPTION LIKE #{keywordPattern} ESCAPE '!' OR LEADER.NICKNAME LIKE #{keywordPattern} ESCAPE '!' )
AND C.CATEGORY_ID = #{categoryId}
AND C.ACTIVITY_REGION LIKE #{regionPattern} ESCAPE '!'
AND C.GENDER_POLICY = #{genderPolicy}
AND (C.MIN_AGE IS NULL OR C.MIN_AGE <= #{age}) AND (C.MAX_AGE IS NULL OR C.MAX_AGE >= #{age})
AND C.RECRUIT_STATUS = #{recruitStatus}

mapper.select:
SELECT (
           SELECT CM.CLUB_ROLE
           FROM HM_CLUB_MEMBER CM
           WHERE CM.CLUB_ID = #{clubId}
             AND CM.MEMBER_ID = #{memberId}
           LIMIT 1
       ) AS memberRole,
       (
           SELECT CM.MEMBER_STATUS
           FROM HM_CLUB_MEMBER CM
           WHERE CM.CLUB_ID = #{clubId}
             AND CM.MEMBER_ID = #{memberId}
           LIMIT 1
       ) AS memberStatus,
       CASE WHEN EXISTS (
           SELECT 1
           FROM HM_CLUB_JOIN_REQUEST JR
           WHERE JR.CLUB_ID = #{clubId}
             AND JR.MEMBER_ID = #{memberId}
             AND JR.REQUEST_STATUS = 'WAITING'
       ) THEN 'Y' ELSE 'N' END AS pendingJoinYn,
       CASE WHEN EXISTS (
           SELECT 1
           FROM HM_CLUB_BAN CB
           WHERE CB.CLUB_ID = #{clubId}
             AND CB.MEMBER_ID = #{memberId}
             AND CB.ACTIVE_YN = 'Y'
       ) THEN 'Y' ELSE 'N' END AS permanentBanYn,
       (
           SELECT MAX(CH.REJOIN_AVAILABLE_AT)
           FROM HM_CLUB_MEMBER_HISTORY CH
           WHERE CH.CLUB_ID = #{clubId}
             AND CH.MEMBER_ID = #{memberId}
             AND CH.EVENT_TYPE IN ('LEFT', 'KICKED')
       ) AS rejoinAvailableAt
